#!/usr/bin/env python3
"""Regenerate the committed *-short summaries from the full generated files.

The full files (logs/, snapshots/, notes/*.txt) are gitignored and stay where the
collection scripts write them. This script produces compact, sanitized excerpts:

  logs-short/key-lines.md        - whitelisted log lines, tokens/tickets removed
  snapshots-short/marker-values.md - small marker values + MD5s, no inventories

Usage: python scripts/make_short.py
"""
import hashlib
import os
import re

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
LOGS = os.path.join(BASE, "logs")
SNAPS = os.path.join(BASE, "snapshots")

KEY = re.compile(
    r"IsBaseResVersionHashChanged|DownloadPref load pref file failed|"
    r"clear revision files|Load DownloadPref|Save DownloadPref|"
    r"Wrote \d+ persistent code switches|OnConnectRegionDispatch|"
    r"Not set common res exist flag|File num to verify|CheckAllFinish|"
    r"FilesDownloadPipe|OnDownloadBunddleFinish|DeserializeBinary"
)
REDACT = re.compile(r"risk_ticket|verify_str|cookie|token=|Authorization|uid:", re.I)


def sanitize(line):
    line = line.rstrip("\n")
    if REDACT.search(line):
        return "[redacted: line contained a ticket/token/uid]"
    if len(line) > 160:
        return line[:160] + " ... [JSON truncated]"
    return line


def short_logs():
    labels = ["(E: baseline sessions)", "after-launch", "second-launch",
              "ablation-A", "ablation-B", "ablation-C"]
    out = ["# Key log lines (sanitized excerpts)", "",
           "Generated by `scripts/make_short.py` from the gitignored full logs in `logs/`.",
           "Lines containing tickets/tokens/uids are redacted; long JSON is truncated.", ""]
    for label in labels:
        path = os.path.join(LOGS, "(root)" if label.startswith("(E:") else label,
                            "output_log.txt")
        if label.startswith("(E:"):
            path = os.path.join(LOGS, "output_log.txt.last")
        if not os.path.isfile(path):
            continue
        out += [f"## {label}", "", "```text"]
        hits = [sanitize(l) for l in open(path, encoding="utf-8", errors="replace") if KEY.search(l)]
        # keep at most one DeserializeBinary line per log to stay compact
        seen = 0
        pref = 0
        kept = []
        for line in hits:
            if "DeserializeBinary" in line:
                seen += 1
                if seen > 1:
                    continue
            if "DownloadPref" in line:
                pref += 1
                if pref > 2:
                    continue
            kept.append(line)
        out += kept[:40] or ["(no matching lines)"]
        out += ["```", ""]
    info = os.path.join(LOGS, "info.txt")
    if os.path.isfile(info):
        v = next((l.strip() for l in open(info, encoding="utf-8") if l.startswith("version:")), "")
        out += ["## info.txt version line", "", "```text", v, "```", ""]
    dest = os.path.join(BASE, "logs-short")
    os.makedirs(dest, exist_ok=True)
    with open(os.path.join(dest, "key-lines.md"), "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(out))


def short_snapshots():
    rows = []
    groups = [("E", os.path.join(SNAPS, "E-marker-files")),
              ("F-after-launch", os.path.join(SNAPS, "F-after-launch")),
              ("F-ablation-A", os.path.join(SNAPS, "F-ablation-A"))]
    names = ["base_res_version_hash", "res_revision", "res_revision_eternal",
             "data_revision", "silence_revision", "audio_revision", "PatchDone",
             "base_revision", "ChannelName", "ScriptVersion", "audio_lang_14",
             "text_lang", "CodeSwitch.config", "test_file"]
    for label, folder in groups:
        rows += [f"## {label}", "", "| file | value (CRLF shown as `\\r\\n`) |",
                 "|---|---|"]
        for name in names:
            p = os.path.join(folder, name)
            if os.path.isfile(p):
                txt = open(p, encoding="utf-8", errors="replace").read()
                txt = txt.replace("\r", "\\r").replace("\n", "\\n").replace("|", "\\|")
                rows.append(f"| `{name}` | `{txt}` |")
        for name in ("res_versions_persist", "data_versions_persist",
                     "silence_data_versions_persist"):
            p = os.path.join(folder, name)
            if os.path.isfile(p):
                digest = hashlib.md5(open(p, "rb").read()).hexdigest()
                rows.append(f"| `{name}` | MD5 `{digest}` (full file gitignored) |")
        rows.append("")
    dest = os.path.join(BASE, "snapshots-short")
    os.makedirs(dest, exist_ok=True)
    with open(os.path.join(dest, "marker-values.md"), "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(["# Marker values (compact excerpts)", "",
                           "Generated by `scripts/make_short.py`; full files live in the gitignored "
                           "`snapshots/` and are regenerated by `snapshot.py` / "
                           "`collect_after_launch.py` / `ablation.py`.", ""] + rows))


if __name__ == "__main__":
    short_logs()
    short_snapshots()
    print("wrote logs-short/key-lines.md and snapshots-short/marker-values.md")
